const message = ($json.body.message || '').toLowerCase();
let reply = '';
let chips = [];

if (message.includes('ungu') || message.includes('cahaya')) {
  reply = 'Kamu melangkah mendekati cahaya ungu. Sebuah Rune Kuno di dinding menyala benderang! Sesosok Peri Roh pelindung menampakkan diri: *\"Sebutkan tujuanmu, pengembara fana! Apakah kamu mencari ilmu terlarang atau emas?\"*';
  chips = ['Jawab: Mencari ilmu terlarang', 'Jawab: Mencari jalan pulang', 'Siapkan pedang untuk berjaga'];
} else if (message.includes('lumut') || message.includes('basah')) {
  reply = 'Lantai lorong berlumut terasa licin dan dingin. Di kejauhan terdengar dengkuran monster Orc yang tertidur di samping peti harta karun besi berkarat.';
  chips = ['Buka peti secara perlahan', 'Sembunyi di balik pilar', 'Nyalakan obor lebih terang'];
} else if (message.includes('ransel') || message.includes('inventaris')) {
  reply = 'Isi ransel petualangmu:\n- 1x Belati Baja Valdorath\n- 1x Ramuan Penyembuh (Heal +50 HP)\n- 1x Tali Tambang 10m\n- 15 Keping Emas Kuno';
  chips = ['Masuk ke lorong ungu', 'Masuk ke lorong berlumut', 'Teguk ramuan penyembuh'];
} else {
  reply = `Sebagai Dungeon Master, tindakanmu dicatat: \"${$json.body.message}\". Langkahmu menggetarkan batu labirin kuno dan membuka relung rahasia di dinding!`;
  chips = ['Periksa relung rahasia', 'Maju dengan waspada', 'Analisis simbol kuno'];
}

return { json: { content: reply, chips: chips } };
